import React, { useState, useRef, useEffect } from 'react';
import { Layout } from './components/Layout';
import { Button } from './components/Button';
import { generateText } from './services/geminiService';
import { ChatMessage, Role } from './types';
import { SAMPLE_PROMPTS } from './constants';
import ReactMarkdown from 'react-markdown'; // Assuming we can use this, but if not I will render text directly. The instructions say "Use popular... libraries". I'll use simple text rendering to be safe and dependency-free within the requested XML block constraints, or just map new lines.

// Simple text renderer to avoid complex external dependencies for this specific output format if not requested.
const MessageContent: React.FC<{ text: string }> = ({ text }) => {
  return (
    <div className="prose prose-slate max-w-none text-slate-800 leading-relaxed whitespace-pre-wrap">
      {text}
    </div>
  );
};

const App: React.FC = () => {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = async (text: string) => {
    if (!text.trim() || isLoading) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: Role.USER,
      text: text,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const responseText = await generateText(text);

      const modelMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: Role.MODEL,
        text: responseText,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      const errorMessage: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: Role.MODEL,
        text: "I'm sorry, I encountered an error while processing your request. Please try again later.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage(input);
    }
  };

  return (
    <Layout>
      <div className="flex flex-col h-full max-w-5xl mx-auto w-full">

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
          {messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center space-y-8 animate-fade-in">
              <div className="max-w-md space-y-4">
                <div className="w-20 h-20 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl mx-auto shadow-xl flex items-center justify-center text-white text-3xl font-bold mb-6">
                  ✨
                </div>
                <h2 className="text-3xl font-bold text-slate-900 tracking-tight">Welcome to PeynirEkmek</h2>
                <p className="text-slate-600 text-lg">
                  This is a blank slate application supercharged with the Gemini 3 Flash model. 
                  Start by typing a message or selecting a prompt below.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 w-full max-w-2xl mt-8">
                {SAMPLE_PROMPTS.map((prompt, idx) => (
                  <button
                    key={idx}
                    onClick={() => handleSendMessage(prompt)}
                    className="text-left p-4 rounded-xl border border-slate-200 bg-white hover:border-indigo-300 hover:shadow-md transition-all duration-200 group"
                  >
                    <p className="text-sm font-medium text-slate-900 group-hover:text-indigo-700 transition-colors">{prompt}</p>
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <>
              {messages.map((msg) => (
                <div 
                  key={msg.id} 
                  className={`flex w-full ${msg.role === Role.USER ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`
                    max-w-[85%] md:max-w-[75%] rounded-2xl px-6 py-4 shadow-sm
                    ${msg.role === Role.USER 
                      ? 'bg-indigo-600 text-white rounded-tr-none' 
                      : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none'
                    }
                  `}>
                    {msg.role === Role.MODEL && (
                      <div className="flex items-center gap-2 mb-2 text-xs font-semibold uppercase tracking-wider text-indigo-500">
                        <span className="w-2 h-2 rounded-full bg-indigo-500"></span>
                        Gemini
                      </div>
                    )}
                    <MessageContent text={msg.text} />
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex w-full justify-start animate-pulse">
                  <div className="bg-white border border-slate-200 rounded-2xl rounded-tl-none px-6 py-4 shadow-sm">
                    <div className="flex gap-1.5 items-center h-6">
                      <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                      <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                      <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white border-t border-slate-200 md:p-6">
          <div className="relative max-w-4xl mx-auto flex items-end gap-3 p-2 bg-slate-50 border border-slate-200 rounded-2xl focus-within:ring-2 focus-within:ring-indigo-500/20 focus-within:border-indigo-500 transition-all shadow-inner">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Type your message here..."
              className="w-full bg-transparent border-0 focus:ring-0 p-3 min-h-[50px] max-h-[150px] resize-none text-slate-800 placeholder-slate-400"
              rows={1}
            />
            <div className="pb-2 pr-2">
              <Button 
                onClick={() => handleSendMessage(input)} 
                disabled={!input.trim() || isLoading}
                className="!rounded-xl !p-2.5 aspect-square flex items-center justify-center"
              >
                <svg className="w-5 h-5 transform rotate-90" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </Button>
            </div>
          </div>
          <div className="text-center mt-3">
             <p className="text-xs text-slate-400">Powered by Google Gemini 3 Flash Preview</p>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default App;

