import { AppConfig } from "../types";

// Extended types for File System Access API which might not be in all TS envs
interface FileSystemHandle {
  kind: 'file' | 'directory';
  name: string;
}

interface FileSystemFileHandle extends FileSystemHandle {
  getFile: () => Promise<File>;
  createWritable: () => Promise<FileSystemWritableFileStream>;
  queryPermission: (descriptor: { mode: 'read' | 'readwrite' }) => Promise<PermissionState>;
  requestPermission: (descriptor: { mode: 'read' | 'readwrite' }) => Promise<PermissionState>;
}

interface FileSystemWritableFileStream extends WritableStream {
  write: (data: string) => Promise<void>;
  close: () => Promise<void>;
}

type PermissionState = 'granted' | 'denied' | 'prompt';

// --- IndexedDB Persistence for Handles ---
const DB_NAME = 'PeynirEkmekDB';
const STORE_NAME = 'handles';
const HANDLE_KEY = 'config_handle';

const initDB = (): Promise<IDBDatabase> => {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
};

export const saveHandleToDB = async (handle: FileSystemFileHandle) => {
  try {
    const db = await initDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    tx.objectStore(STORE_NAME).put(handle, HANDLE_KEY);
  } catch (err) {
    console.warn("IndexedDB save failed:", err);
  }
};

export const getHandleFromDB = async (): Promise<FileSystemFileHandle | null> => {
  try {
    const db = await initDB();
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, 'readonly');
      const req = tx.objectStore(STORE_NAME).get(HANDLE_KEY);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (err) {
    console.warn("IndexedDB load failed:", err);
    return null;
  }
};

// --- LocalStorage Persistence for Config ---
const STORAGE_KEY = 'peynirekmek_config_cache';

export const saveConfigToLocalStorage = (config: AppConfig) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.warn("LocalStorage save failed", e);
  }
};

export const getConfigFromLocalStorage = (): AppConfig | null => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
};

// --- File System Access API ---

export const isFileSystemSupported = () => 'showOpenFilePicker' in window;

export const loadConfigFromFile = async (): Promise<{ config: AppConfig, handle: FileSystemFileHandle | null }> => {
  // Try Modern API
  if (isFileSystemSupported()) {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [
          {
            description: 'JSON Configuration',
            accept: {
              'application/json': ['.json'],
            },
          },
        ],
        multiple: false,
      });

      const file = await handle.getFile();
      const text = await file.text();
      const config = JSON.parse(text);

      // Persist handle and config immediately
      await saveHandleToDB(handle);
      saveConfigToLocalStorage(config);

      return { config, handle };
    } catch (err) {
      if ((err as Error).name === 'AbortError') throw err;
      console.warn("File System API failed, falling back to legacy input", err);
    }
  }

  // Legacy Fallback
  return new Promise((resolve, reject) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json,application/json';
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        try {
            const text = await file.text();
            const config = JSON.parse(text);
            saveConfigToLocalStorage(config);
            resolve({ config, handle: null });
        } catch (error) {
            reject(error);
        }
      }
    };
    input.click();
  });
};

export const saveConfigToFile = async (config: AppConfig, handle: FileSystemFileHandle | null): Promise<FileSystemFileHandle | null> => {
  // Always update local cache first
  saveConfigToLocalStorage(config);

  // 1. If we have a valid handle, try writing to it
  if (handle) {
    try {
      // Check/Request permission if needed (must be user gesture for prompt)
      // Note: 'createWritable' often triggers the permission prompt automatically in Chrome if not granted.
      // @ts-ignore
      const writable = await handle.createWritable();
      await writable.write(JSON.stringify(config, null, 2));
      await writable.close();
      return handle;
    } catch (err) {
      console.warn("Failed to write to existing handle:", err);
      // We don't automatically fall back to 'Save As' here to avoid annoying popups on every auto-save attempt.
      // Instead, we throw so the UI can show a "Reconnect" button.
      throw new Error("Permission or Handle invalid");
    }
  }

  // 2. Try creating a new handle (Save As) - Explicit user action usually
  if (isFileSystemSupported()) {
    try {
      // @ts-ignore
      const newHandle = await window.showSaveFilePicker({
        suggestedName: 'landing-page-config.json',
        types: [{
          description: 'JSON Configuration',
          accept: { 'application/json': ['.json'] },
        }],
      });

      // @ts-ignore
      const writable = await newHandle.createWritable();
      await writable.write(JSON.stringify(config, null, 2));
      await writable.close();

      await saveHandleToDB(newHandle);
      return newHandle;
    } catch (err) {
      if ((err as Error).name === 'AbortError') throw err;
      console.warn("File System Save API failed, falling back to download", err);
    }
  }

  // 3. Last Resort: Trigger Download
  downloadConfigFallback(config);
  return null;
};

// Fallback for browsers without File System Access API
export const downloadConfigFallback = (config: AppConfig) => {
  const blob = new Blob([JSON.stringify(config, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'landing-page-config.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

import React, { useState, useEffect, useCallback } from 'react';
import { Lock, LogOut } from 'lucide-react';
import { AppConfig, ButtonConfig } from './types';
import { 
  loadConfigFromFile, 
  saveConfigToFile, 
  getConfigFromLocalStorage, 
  getHandleFromDB,
  saveConfigToLocalStorage
} from './services/fileService';
import DynamicButton from './components/DynamicButton';
import AdminPanel from './components/AdminPanel';

function App() {
  const [config, setConfig] = useState<AppConfig>({ siteTitle: 'My Links', buttons: [] });
  const [fileHandle, setFileHandle] = useState<any>(null); // FileSystemFileHandle
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminPanel, setShowAdminPanel] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [syncError, setSyncError] = useState(false);

  // Login State
  const [showLogin, setShowLogin] = useState(false);
  const [passwordInput, setPasswordInput] = useState('');

  // Hidden Trigger State
  const [triggerCount, setTriggerCount] = useState(0);

  // Initialize from LocalStorage and IndexedDB on mount
  useEffect(() => {
    const init = async () => {
      // 1. Load Data from LocalStorage (Immediate Persistence)
      const cachedConfig = getConfigFromLocalStorage();
      if (cachedConfig) {
        setConfig(cachedConfig);
      }

      // 2. Try to restore File Handle from IndexedDB (Cloud Sync Persistence)
      const storedHandle = await getHandleFromDB();
      if (storedHandle) {
        setFileHandle(storedHandle);
        // Note: We can't verify permission here without user gesture, 
        // but having the handle allows us to prompt later or save if permission persists.
      }
    };
    init();
  }, []);

  // Hidden Login Trigger Logic (Clicking copyright 5 times)
  const handleHiddenTrigger = () => {
    setTriggerCount(prev => prev + 1);
    if (triggerCount + 1 >= 5) {
      if (isAdmin) {
          setShowAdminPanel(true);
      } else {
          setShowLogin(true);
      }
      setTriggerCount(0);
    }
  };

  // Keyboard shortcut (Ctrl+Shift+L)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key === 'L') {
        e.preventDefault();
        if (isAdmin) setShowAdminPanel(true);
        else setShowLogin(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === 'R0b0t0lg@') {
      setIsAdmin(true);
      setShowLogin(false);
      setShowAdminPanel(true);
      setPasswordInput('');
    } else {
      alert('Incorrect Password');
    }
  };

  // File Operations
  const handleOpenFile = async () => {
    try {
      const { config: loadedConfig, handle } = await loadConfigFromFile();
      setConfig(loadedConfig);
      setFileHandle(handle);
      setSyncError(false);
    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
        alert("Failed to open file.");
      }
    }
  };

  const handleCreateFile = async () => {
    try {
      // Create a new handle with current config
      const handle = await saveConfigToFile(config, null);
      setFileHandle(handle);
      setSyncError(false);
    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
         alert("Failed to create file.");
      }
    }
  };

  // Centralized update function that handles state and auto-saving
  const updateButtons = async (newButtons: ButtonConfig[]) => {
    const newConfig = { ...config, buttons: newButtons };
    setConfig(newConfig);

    // Always persist to local storage immediately
    saveConfigToLocalStorage(newConfig);

    if (fileHandle) {
      setIsSaving(true);
      setSyncError(false);
      try {
        await saveConfigToFile(newConfig, fileHandle);
      } catch (err) {
        console.error("Auto-save failed:", err);
        setSyncError(true);
        // Don't alert here, let the UI show the sync error state
      } finally {
        setIsSaving(false);
      }
    }
  };

  // Function to retry sync (explicit user action which allows permission prompt)
  const retrySync = async () => {
    if (fileHandle) {
      setIsSaving(true);
      try {
        await saveConfigToFile(config, fileHandle);
        setSyncError(false);
      } catch (e) {
        alert("Could not re-establish connection to file. Please open the file again.");
      } finally {
        setIsSaving(false);
      }
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative">

      {/* Background Ambient Effects */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-900/20 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/20 rounded-full blur-[100px]"></div>
      </div>

      <main className="w-full max-w-lg flex flex-col items-center gap-6 animate-fade-in">

        {/* Buttons Grid */}
        <div className="w-full space-y-4">
          {config.buttons.length === 0 && (
              <div className="text-center text-slate-500 py-10 border border-dashed border-slate-800 rounded-xl">
                  <p>No buttons configured.</p>
                  <p className="text-xs mt-2 opacity-50">Admin: Open a file to start.</p>
              </div>
          )}
          {config.buttons.map(btn => (
            <DynamicButton key={btn.id} config={btn} />
          ))}
        </div>

      </main>

      {/* Footer / Hidden Login Area */}
      <footer className="mt-16 text-center">
        <div 
          onClick={handleHiddenTrigger}
          className="inline-block p-2 text-slate-600 text-xs hover:text-slate-500 cursor-default select-none transition-colors"
        >
          © 2026 Peynirekmek.com
        </div>
        {isAdmin && (
            <div className="mt-2 flex items-center justify-center gap-4 text-xs">
                <button onClick={() => setShowAdminPanel(true)} className="text-purple-400 hover:underline">
                    Open Admin
                </button>
                 <button onClick={() => setIsAdmin(false)} className="text-red-400 hover:underline flex items-center gap-1">
                    <LogOut size={10} /> Logout
                </button>
            </div>
        )}
      </footer>

      {/* Admin Panel Modal */}
      {showAdminPanel && (
        <AdminPanel 
          buttons={config.buttons}
          setButtons={updateButtons}
          onOpenFile={handleOpenFile}
          onCreateFile={handleCreateFile}
          isFileConnected={!!fileHandle}
          onClose={() => setShowAdminPanel(false)}
          isSaving={isSaving}
        />
      )}

      {/* Global Sync Error Toast (Admin only) */}
      {isAdmin && syncError && showAdminPanel && (
         <div className="fixed bottom-4 right-4 bg-red-900/90 text-white px-4 py-3 rounded-lg shadow-xl z-[60] flex items-center gap-3 border border-red-700">
           <div className="text-sm">
             <p className="font-bold">Sync Paused</p>
             <p className="text-xs text-red-200">Permission lost or file moved.</p>
           </div>
           <button 
             onClick={retrySync}
             className="bg-white text-red-900 text-xs font-bold px-3 py-1.5 rounded hover:bg-red-50"
           >
             Reconnect
           </button>
         </div>
      )}

      {/* Login Modal */}
      {showLogin && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4 animate-fade-in">
          <form onSubmit={handleLogin} className="bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700 w-full max-w-sm text-center space-y-6">
            <div className="w-16 h-16 bg-slate-700 rounded-full flex items-center justify-center mx-auto text-purple-400">
                <Lock size={32} />
            </div>
            <div>
                <h3 className="text-xl font-bold text-white">Admin Access</h3>
                <p className="text-slate-400 text-sm">Enter password to manage buttons</p>
            </div>
            <input 
              type="password" 
              autoFocus
              value={passwordInput}
              onChange={e => setPasswordInput(e.target.value)}
              className="w-full bg-slate-900 border border-slate-600 rounded-lg p-3 text-white text-center tracking-widest focus:ring-2 focus:ring-purple-500 outline-none"
              placeholder="••••••••"
            />
            <div className="flex gap-2">
                <button 
                    type="button"
                    onClick={() => { setShowLogin(false); setPasswordInput(''); }}
                    className="flex-1 py-2 text-slate-400 hover:text-white"
                >
                    Cancel
                </button>
                <button 
                    type="submit"
                    className="flex-1 bg-purple-600 hover:bg-purple-700 text-white py-2 rounded-lg font-medium"
                >
                    Unlock
                </button>
            </div>
          </form>
        </div>
      )}

    </div>
  );
}

export default App;

