    const init = async () => {
      setIsLoading(true);

      // 1. Check URL for ?binId=... (Priority: Cloud via URL)
      const params = new URLSearchParams(window.location.search);
      const urlBinId = params.get('binId');

      // Load saved settings
      const savedCloudSettings = getCloudSettings();
      if (savedCloudSettings) setCloudSettings(savedCloudSettings);

      if (urlBinId) {
        try {
          // If we have a binId in URL, we try to fetch it.
