          setConfig(cloudConfig);

          // Update local settings to match this URL context if it's different (optional, but good for persistence)
          if (savedCloudSettings?.binId !== urlBinId) {
             // We don't overwrite settings automatically to avoid overwriting Admin keys with public view data
             // But we do set the content.
          }
          setIsLoading(false);
          return; // Exit, we found our data source
        } catch (e) {
          console.error("Failed to load from URL Bin ID", e);
        }
      }

      // 2. Fallback: Load from LocalStorage (Immediate Persistence)
      const cachedConfig = getConfigFromLocalStorage();
      if (cachedConfig) {
        setConfig(cachedConfig);
      }

      // 3. Try to restore File Handle
      const storedHandle = await getHandleFromDB();
      if (storedHandle) {
        setFileHandle(storedHandle);
      }

      setIsLoading(false);
    };
    init();
  }, []);

  // Hidden Login Trigger Logic
  const handleHiddenTrigger = () => {
    setTriggerCount(prev => prev + 1);
    if (triggerCount + 1 >= 5) {
      if (isAdmin) {
          setShowAdminPanel(true);
      } else {
          setShowLogin(true);
      }
      setTriggerCount(0);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.ctrlKey && e.shiftKey && e.key === 'L') {
        e.preventDefault();
        if (isAdmin) setShowAdminPanel(true);
        else setShowLogin(true);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isAdmin]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordInput === 'R0b0t0lg@') {
      setIsAdmin(true);
      setShowLogin(false);
      setShowAdminPanel(true);
      setPasswordInput('');
    } else {
      alert('Incorrect Password');
    }
  };

  // --- Data Management ---

  const handleOpenFile = async () => {
    try {
      const { config: loadedConfig, handle } = await loadConfigFromFile();
      setConfig(loadedConfig);
      setFileHandle(handle);
      setSyncError(false);
    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
        alert("Failed to open file.");
      }
    }
  };

  const handleCreateFile = async () => {
    try {
      const handle = await saveConfigToFile(config, null);
      setFileHandle(handle);
      setSyncError(false);
    } catch (err) {
      if ((err as Error).name !== 'AbortError') {
         alert("Failed to create file.");
      }
    }
  };

  const handleSyncToCloud = async () => {
    if (!cloudSettings?.apiKey) {
      alert("Please enter an API Key first.");
      return;
    }

    setIsCloudSyncing(true);
    try {
      let newBinId = cloudSettings.binId;

      if (!newBinId) {
        // Create new
        newBinId = await createCloudBin(config, cloudSettings.apiKey);
        const newSettings = { ...cloudSettings, binId: newBinId };
        setCloudSettings(newSettings);
        saveCloudSettings(newSettings);
        alert(`Cloud Bin Created! ID: ${newBinId}`);
      } else {
        // Update existing
        await saveToCloud(config, newBinId, cloudSettings.apiKey);
      }

      // Update URL to reflect the bin (without reloading)
      const url = new URL(window.location.href);
      url.searchParams.set('binId', newBinId);
      window.history.pushState({}, '', url);

    } catch (e) {
      console.error(e);
      alert("Cloud Sync failed. Check console for details.");
    } finally {
      setIsCloudSyncing(false);
    }
  };

  const updateButtons = async (newButtons: ButtonConfig[]) => {
    const newConfig = { ...config, buttons: newButtons };
    setConfig(newConfig);

    // 1. Local Storage
    saveConfigToLocalStorage(newConfig);

    // 2. File System (if connected)
    if (fileHandle) {
      setIsSaving(true);
      try {
        await saveConfigToFile(newConfig, fileHandle);
        setSyncError(false);
      } catch (err) {
        console.error("File Auto-save failed:", err);
        setSyncError(true);
      } finally {
        setIsSaving(false);
      }
    }

    // 3. Cloud (if configured)
    if (cloudSettings?.autoSync && cloudSettings.binId && cloudSettings.apiKey) {
      setIsCloudSyncing(true);
      try {
        await saveToCloud(newConfig, cloudSettings.binId, cloudSettings.apiKey);
      } catch (err) {
        console.error("Cloud Auto-save failed:", err);
      } finally {
        setIsCloudSyncing(false);
      }
    }
  };

  const retryFileSync = async () => {
    if (fileHandle) {
      setIsSaving(true);
      try {
        await saveConfigToFile(config, fileHandle);
        setSyncError(false);
      } catch (e) {
        alert("Connection lost. Please open file again.");
      } finally {
        setIsSaving(false);
      }
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900">
        <Loader2 className="animate-spin text-purple-500" size={48} />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative">

      {/* Background Ambient Effects */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-900/20 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/20 rounded-full blur-[100px]"></div>
      </div>

      <main className="w-full max-w-lg flex flex-col items-center gap-6 animate-fade-in">

        {/* Buttons Grid */}
        <div className="w-full space-y-4">
          {config.buttons.length === 0 && (
              <div className="text-center text-slate-500 py-10 border border-dashed border-slate-800 rounded-xl">
                  <p>No buttons configured.</p>
                  <p className="text-xs mt-2 opacity-50">Admin: Configure Cloud or File to start.</p>
              </div>
          )}
          {config.buttons.map(btn => (
            <DynamicButton key={btn.id} config={btn} />
          ))}
        </div>

      </main>

      {/* Footer / Hidden Login Area */}
      <footer className="mt-16 text-center">
        <div 
          onClick={handleHiddenTrigger}
          className="inline-block p-2 text-slate-600 text-xs hover:text-slate-500 cursor-default select-none transition-colors"
        >
          © 2026 Peynirekmek.com
        </div>
        {isAdmin && (
            <div className="mt-2 flex items-center justify-center gap-4 text-xs">
                <button onClick={() => setShowAdminPanel(true)} className="text-purple-400 hover:underline">
                    Open Admin
                </button>
                 <button onClick={() => setIsAdmin(false)} className="text-red-400 hover:underline flex items-center gap-1">
                    <LogOut size={10} /> Logout
                </button>
            </div>
        )}
      </footer>

      {/* Admin Panel Modal */}
      {showAdminPanel && (
        <AdminPanel 
          buttons={config.buttons}
          setButtons={updateButtons}
          onOpenFile={handleOpenFile}
          onCreateFile={handleCreateFile}
          isFileConnected={!!fileHandle}
          onClose={() => setShowAdminPanel(false)}
          isSaving={isSaving}
          cloudSettings={cloudSettings}
          onUpdateCloudSettings={(s) => {
             setCloudSettings(s);
             saveCloudSettings(s);
          }}
          onSyncToCloud={handleSyncToCloud}
          isCloudSyncing={isCloudSyncing}
        />
      )}

      {/* File Sync Error Toast */}
      {isAdmin && syncError && showAdminPanel && (
         <div className="fixed bottom-4 right-4 bg-red-900/90 text-white px-4 py-3 rounded-lg shadow-xl z-[60] flex items-center gap-3 border border-red-700">
           <div className="text-sm">
             <p className="font-bold">File Sync Paused</p>
             <p className="text-xs text-red-200">Permission lost or file moved.</p>
           </div>
           <button 
