// Custom plugin to handle saving config.json to the project root
const saveConfigPlugin = () => ({
  name: 'save-config-middleware',
  configureServer(server) {
    server.middlewares.use('/api/save-config', (req, res, next) => {
      if (req.method === 'POST') {
        let body = '';
        req.on('data', chunk => {
          body += chunk.toString();
        });
        req.on('end', () => {
          try {
             // Validate that it's valid JSON before writing
             JSON.parse(body); 

             // Write to project root
             const filePath = path.resolve(__dirname, 'config.json');
             fs.writeFileSync(filePath, body);

             console.log(`[Server] Configuration saved to ${filePath}`);

             res.setHeader('Content-Type', 'application/json');
             res.end(JSON.stringify({ success: true }));
          } catch (e) {
             console.error("[Server] Error saving config:", e);
             res.statusCode = 500;
             res.end(JSON.stringify({ error: 'Failed to save config file.' }));
          }
        });
      } else {
        next();
      }
    });
  }
});

