import { AppConfig } from "../types";

const STORAGE_KEY = 'peynirekmek_config';
const CONFIG_FILENAME = 'config.json';

// --- Core Data Loading ---

export const loadConfig = async (): Promise<AppConfig> => {
  let config: AppConfig = { siteTitle: 'LinkForge', buttons: [] };
  let loadedFrom = 'default';

  // 1. Try to fetch 'config.json' from the server
  try {
    // Add timestamp to prevent caching
    const response = await fetch(`/${CONFIG_FILENAME}?t=${Date.now()}`); 
    if (response.ok) {
      const serverConfig = await response.json();
      if (isValidConfig(serverConfig)) {
        config = serverConfig;
        loadedFrom = 'server';

        // Update local storage to match server so they are in sync
        saveToLocalStorage(serverConfig);
      }
    }
  } catch (err) {
    console.log("No config.json found on server.");
  }

  // 2. If server failed or we have newer local changes (optional logic, strictly adhering to server priority here for consistency across browsers)
  // However, for admin editing, we often read from localStorage if it exists and differs. 
  // For this request, we prioritize the SERVER file to ensure "what you see is what everyone sees".
  // Local storage acts as a draft buffer.

  console.log(`Config loaded from: ${loadedFrom}`);
  return config;
};

// --- Server Persistence (The "Real" Save) ---

export const publishConfig = async (config: AppConfig): Promise<void> => {
  try {
    const response = await fetch('/api/save-config', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(config, null, 2),
    });

    if (!response.ok) {
      throw new Error('Server returned error');
    }

    // Update local storage to match
    saveToLocalStorage(config);

  } catch (e) {
    console.error("Publish failed:", e);
    throw new Error("Failed to write to server. Are you running the dev server?");
  }
};

// --- Persist to LocalStorage (Drafts) ---
export const saveToLocalStorage = (config: AppConfig) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.error("LocalStorage Save Failed", e);
  }
};

export const clearLocalStorage = () => {
  localStorage.removeItem(STORAGE_KEY);
};

// --- Manual File Operations (Backup/Restore) ---

export const downloadConfigJSON = (config: AppConfig) => {
  const dataStr = JSON.stringify(config, null, 2);
  const blob = new Blob([dataStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = CONFIG_FILENAME;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const importConfigJSON = async (file: File): Promise<AppConfig> => {
  const text = await file.text();
  const config = JSON.parse(text);
  if (!isValidConfig(config)) {
    throw new Error("Invalid configuration file format.");
  }
  saveToLocalStorage(config);
  return config;
};

// --- Helper ---
function isValidConfig(obj: any): obj is AppConfig {
  return obj && Array.isArray(obj.buttons);
}

