import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';
import { Buffer } from 'buffer';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Helper to setup the config saving middleware
const setupSaveMiddleware = (server: any) => {
  server.middlewares.use('/api/save-config', (req: any, res: any, next: any) => {
    if (req.method === 'POST') {
      const chunks: Buffer[] = [];
      req.on('data', (chunk: Buffer) => chunks.push(chunk));
      req.on('end', () => {
        try {
           const body = Buffer.concat(chunks).toString();
           // Validate that it's valid JSON before writing
           JSON.parse(body); 

           // Write to project root
           const filePath = path.resolve(__dirname, 'config.json');
           fs.writeFileSync(filePath, body);

           console.log(`[Server] Configuration saved to ${filePath}`);

           res.statusCode = 200;
           res.setHeader('Content-Type', 'application/json');
           res.end(JSON.stringify({ success: true }));
        } catch (e) {
           console.error("[Server] Error saving config:", e);
           res.statusCode = 500;
           res.setHeader('Content-Type', 'application/json');
           res.end(JSON.stringify({ error: 'Failed to save config file.' }));
        }
      });

      req.on('error', (err: any) => {
          console.error("Request error", err);
          res.statusCode = 500;
          res.end(JSON.stringify({ error: 'Request stream error' }));
      });
    } else {
      next();
    }
  });
};

const saveConfigPlugin = () => ({
  name: 'save-config-middleware',
  // Hook into both Dev Server and Preview Server
  configureServer(server: any) {
    setupSaveMiddleware(server);
  },
  configurePreviewServer(server: any) {
    setupSaveMiddleware(server);
  }
});

