export const loadConfig = async (): Promise<AppConfig> => {
  // 1. Try LocalStorage (Browser Memory)
  try {
    const local = localStorage.getItem(STORAGE_KEY);
    if (local) {
      const parsed = JSON.parse(local);
      if (isValidConfig(parsed)) {
        console.log("Loaded config from LocalStorage");
        return parsed;
      }
    }
  } catch (e) {
    console.error("Error loading local storage", e);
  }

  // 2. Fallback to Default (User Provided)
  console.log("Using default configuration");
  return DEFAULT_CONFIG;
};

// --- LocalStorage ---
export const saveToLocalStorage = (config: AppConfig) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (e) {
    console.error("LocalStorage Save Failed", e);
  }
};

export const clearLocalStorage = () => {
  localStorage.removeItem(STORAGE_KEY);
};

// --- Manual File Operations ---

export const downloadConfigJSON = (config: AppConfig) => {
  const dataStr = JSON.stringify(config, null, 2);
  const blob = new Blob([dataStr], { type: "application/json" });
  const url = URL.createObjectURL(blob);

  const link = document.createElement('a');
  link.href = url;
  link.download = CONFIG_FILENAME;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
};

export const importConfigJSON = async (file: File): Promise<AppConfig> => {
  const text = await file.text();
  const config = JSON.parse(text);
  if (!isValidConfig(config)) {
    throw new Error("Invalid configuration file format.");
  }
  saveToLocalStorage(config);
  return config;
};

// --- Helper ---
function isValidConfig(obj: any): obj is AppConfig {
  return obj && Array.isArray(obj.buttons);
}

// Remove broken publish logic
export const publishConfig = async (config: AppConfig): Promise<void> => {
  console.warn("Server publishing is disabled. Using local storage only.");
  saveToLocalStorage(config);
  return Promise.resolve();
};

import React, { useState, useRef } from 'react';
import { Plus, Trash2, X, Loader2, Wand2, Upload, Download, RotateCcw } from 'lucide-react';
import { ButtonConfig } from '../types';
import { generateButtonStyle } from '../services/geminiService';
import { downloadConfigJSON, importConfigJSON, saveToLocalStorage } from '../services/fileService';

interface Props {
  buttons: ButtonConfig[];
  setButtons: (buttons: ButtonConfig[]) => void;
  onClose: () => void;
  onResetToPublished: () => void;
}

const AdminPanel: React.FC<Props> = ({ 
  buttons, 
  setButtons, 
  onClose,
  onResetToPublished
}) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newBtn, setNewBtn] = useState({ name: '', url: '', description: '' });
  const [isGenerating, setIsGenerating] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleGenerateAndAdd = async () => {
    if (!newBtn.name || !newBtn.url || !newBtn.description) return;

    setIsGenerating(true);
    try {
      const style = await generateButtonStyle(newBtn.description);
      const newButtonConfig: ButtonConfig = {
        id: crypto.randomUUID(),
        name: newBtn.name,
        url: newBtn.url,
        description: newBtn.description,
        className: style.className,
        iconName: style.icon
      };

      const updatedButtons = [...buttons, newButtonConfig];
      setButtons(updatedButtons);
      setNewBtn({ name: '', url: '', description: '' });
      setIsAdding(false);
    } catch (e) {
      alert("Failed to generate button style. Please try again.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDelete = (id: string) => {
    if (confirm('Are you sure you want to delete this button?')) {
      const updatedButtons = buttons.filter(b => b.id !== id);
      setButtons(updatedButtons);
    }
  };

  const handleExport = () => {
    downloadConfigJSON({ siteTitle: 'My Links', buttons });
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const config = await importConfigJSON(file);
      setButtons(config.buttons);
    } catch (err) {
      alert("Failed to import file. " + err);
    }
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
      <div className="bg-slate-800 border border-slate-700 w-full max-w-2xl rounded-xl shadow-2xl flex flex-col max-h-[90vh] animate-fade-in">

        {/* Header */}
        <div className="p-6 border-b border-slate-700 flex justify-between items-center bg-slate-900/50 rounded-t-xl">
          <h2 className="text-2xl font-bold text-white flex items-center gap-2">
            <Wand2 className="text-purple-400" />
            Admin Panel
          </h2>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <X size={24} />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 flex-1 overflow-y-auto">

          <div className="mb-6 grid grid-cols-2 gap-4">
             {/* Import/Export */}
             <div className="bg-slate-700/30 p-4 rounded-xl border border-slate-600/50">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Configuration</h3>
                <div className="flex gap-2">
                   <button onClick={handleExport} className="flex-1 bg-slate-700 hover:bg-slate-600 text-white text-xs py-2 px-2 rounded-lg flex items-center justify-center gap-1 border border-slate-600">
                      <Download size={14} /> Download
                   </button>
                   <button onClick={handleImportClick} className="flex-1 bg-slate-700 hover:bg-slate-600 text-white text-xs py-2 px-2 rounded-lg flex items-center justify-center gap-1 border border-slate-600">
                      <Upload size={14} /> Upload
                   </button>
                   <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept=".json" />
                </div>
             </div>

             {/* Revert */}
             <div className="bg-slate-700/30 p-4 rounded-xl border border-slate-600/50">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Reset</h3>
                <button onClick={onResetToPublished} className="w-full bg-slate-700 hover:bg-red-900/50 hover:text-red-200 text-slate-300 text-xs py-2 px-3 rounded-lg flex items-center justify-center gap-2 border border-slate-600 transition-colors">
                   <RotateCcw size={14} /> Reset to Defaults
                </button>
             </div>
          </div>

          {/* List of current buttons */}
          <div className="space-y-3 mb-8">
            <h3 className="text-sm font-semibold text-slate-400 uppercase tracking-wider mb-2">Buttons</h3>
            {buttons.length === 0 && (
              <p className="text-slate-500 italic">No buttons created yet.</p>
            )}
            {buttons.map(btn => (
              <div key={btn.id} className="flex items-center justify-between bg-slate-700/50 p-3 rounded-lg border border-slate-700">
                <div className="flex items-center gap-3">
                  <div className={`w-8 h-8 rounded flex items-center justify-center bg-slate-600 text-slate-300`}>
                    <div className="scale-50 origin-center pointer-events-none">
                      <div className="w-4 h-4 bg-white rounded-full"></div>
                    </div>
                  </div>
                  <div>
                    <p className="font-medium text-white">{btn.name}</p>
                    <p className="text-xs text-slate-400 truncate max-w-[200px]">{btn.url}</p>
                  </div>
                </div>
                <button 
                  onClick={() => handleDelete(btn.id)}
                  className="text-red-400 hover:text-red-300 p-2 hover:bg-red-400/10 rounded-lg transition-colors"
                >
                  <Trash2 size={18} />
                </button>
