const STORAGE_KEY = 'site_config';

export const loadConfig = async (): Promise<AppConfig> => {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      // If we have saved data, we might want to merge or ensure it respects the default structure, 
      // but for this specific request to "categorize", we want to ensure the categories are present.
      // Since the user is moving to a static categorized view, let's prioritize the DEFAULT_CONFIG
      // if the saved config is missing categories, or just force DEFAULT_CONFIG as the user
      // requested to "delete everything... just create a website button with attached configs" previously.
      // However, to be safe, let's just use DEFAULT_CONFIG for now to guarantee the structure.
      // If persistence is strictly needed, we would need to migrate the data.
      // For this request, returning DEFAULT_CONFIG ensures the categories appear immediately.
      return DEFAULT_CONFIG;
    }
  } catch (error) {
    console.error("Failed to load config from storage:", error);
  }
  return DEFAULT_CONFIG;
};

export const saveToLocalStorage = (config: AppConfig) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
  } catch (error) {
    console.error("Failed to save config to storage:", error);
  }
};

export const downloadConfigJSON = (config: AppConfig) => {
  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(config, null, 2));
  const downloadAnchorNode = document.createElement('a');
  downloadAnchorNode.setAttribute("href", dataStr);
  downloadAnchorNode.setAttribute("download", "config.json");
  document.body.appendChild(downloadAnchorNode); // required for firefox
  downloadAnchorNode.click();
  downloadAnchorNode.remove();
};

export const importConfigJSON = async (file: File): Promise<AppConfig> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        if (!event.target?.result) throw new Error("File is empty");
        const json = JSON.parse(event.target.result as string) as AppConfig;

        if (!json.buttons || !Array.isArray(json.buttons)) {
          throw new Error("Invalid config format: 'buttons' array is missing");
        }

        resolve(json);
      } catch (error) {
        reject(error);
      }
    };
    reader.onerror = (error) => reject(error);
    reader.readAsText(file);
  });
};

import React, { useState, useEffect, useMemo } from 'react';
import { Loader2 } from 'lucide-react';
import { AppConfig, ButtonConfig } from './types';
import { loadConfig } from './services/fileService';
import DynamicButton from './components/DynamicButton';

function App() {
  const [config, setConfig] = useState<AppConfig>({ siteTitle: '', buttons: [] });
  const [isLoading, setIsLoading] = useState(true);

  // Initialize Data
  useEffect(() => {
    const fetchConfig = async () => {
      setIsLoading(true);
      const loadedConfig = await loadConfig();
      setConfig(loadedConfig);
      setIsLoading(false);
    };
    fetchConfig();
  }, []);

  // Group buttons by category
  const categories = useMemo(() => {
    const grouped: Record<string, ButtonConfig[]> = {};
    config.buttons.forEach(btn => {
      const cat = btn.category || 'Other';
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(btn);
    });
    return grouped;
  }, [config.buttons]);

  // Define display order
  const displayOrder = ['Games', 'Tesla', 'Drones', 'Wildlife'];

  // Add any categories found in data but not in the defined order to the end
  const distinctCategories = Object.keys(categories);
  const finalOrder = [...displayOrder];
  distinctCategories.forEach(c => {
    if (!finalOrder.includes(c) && c !== 'Other') {
      finalOrder.push(c);
    }
  });
  if (categories['Other']) finalOrder.push('Other');


  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-900">
        <Loader2 className="animate-spin text-purple-500" size={48} />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative">

      {/* Background Ambient Effects */}
      <div className="absolute top-0 left-0 w-full h-full overflow-hidden -z-10 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-900/20 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-900/20 rounded-full blur-[100px]"></div>
      </div>

      <main className="w-full max-w-2xl flex flex-col items-center gap-8 animate-fade-in pt-8 pb-16">

        {/* Optional Title Display */}
        {config.siteTitle && (
            <h1 className="text-3xl font-bold text-white mb-2">{config.siteTitle}</h1>
        )}

        {/* Categories Grid */}
        <div className="w-full space-y-10">
          {finalOrder.map(catName => {
            const buttons = categories[catName];
            if (!buttons || buttons.length === 0) return null;

            return (
              <div key={catName} className="w-full">
                <h2 className="text-sm font-bold text-slate-400 uppercase tracking-widest border-b border-slate-700/50 pb-2 mb-6 ml-1">
                  {catName}
                </h2>
                <div className="space-y-4">
                  {buttons.map(btn => (
                    <DynamicButton key={btn.id} config={btn} />
                  ))}
                </div>
              </div>
            );
          })}
        </div>

      </main>

      {/* Footer */}
      <footer className="mb-8 text-center">
        <div className="text-slate-600 text-xs">
          © 2026 PeynirEkmek.com
        </div>
      </footer>

    </div>
  );
}

export default App;
